// Before index: COLLSCAN — reads every document
const user = await users.findOne({ email: 'alice@example.com' });
// On 1M documents: ~300ms

// Create the index
await users.createIndex({ email: 1 });

// After index: IXSCAN — jumps directly to 'alice'
const user2 = await users.findOne({ email: 'alice@example.com' });
// On 1M documents: ~1ms

// Verify with explain()
const plan = await users.find({ email: 'alice@example.com' }).explain('executionStats');
console.log(plan.queryPlanner.winningPlan.stage);              // FETCH (good)
console.log(plan.queryPlanner.winningPlan.inputStage.stage);   // IXSCAN (good)
console.log(plan.executionStats.totalDocsExamined);            // 1 (excellent!)

// Single-field index (1 = ascending, -1 = descending)
await users.createIndex({ email: 1 });
await orders.createIndex({ placedAt: -1 });  // descending — for newest-first queries

// Unique index — rejects duplicate values
await users.createIndex({ email: 1 }, { unique: true });

// Compound index — covers multi-field queries
// Use ESR rule: Equality, Sort, Range
await products.createIndex({ category: 1, price: -1 });
// Covers: find({ category: 'Electronics' }).sort({ price: -1 })

// Sparse index — only indexes documents where the field exists
await users.createIndex({ phone: 1 }, { sparse: true });
// Documents without 'phone' are excluded from this index

// TTL index — auto-delete after N seconds
await sessions.createIndex({ createdAt: 1 }, { expireAfterSeconds: 86400 });

// Partial index — index only documents matching a filter
await orders.createIndex(
  { customerId: 1, placedAt: -1 },
  { partialFilterExpression: { status: 'active' } }  // only index active orders
);
// Smaller and faster than a full index on these fields

// Query: find active Electronics products, sorted by price, filtered to price < 5000
const q = products.find(
  { status: 'active', category: 'Electronics', price: { $lt: 5000 } }
).sort({ price: 1 });

// BAD index order:
await products.createIndex({ price: 1, status: 1, category: 1 });
// Range field first — MongoDB can't use the index efficiently for status/category

// GOOD index order (ESR):
// Equality: status=active, category=Electronics (exact matches first)
// Sort: price (sort field next)
// Range: price < 5000 (range field last)
await products.createIndex({ status: 1, category: 1, price: 1 });
// Now MongoDB scans the minimum index range needed

// A compound index (a, b, c) also covers queries on:
//   (a), (a, b), (a, b, c)
// But NOT (b), (c), (b, c) — the prefix rule applies

// Get the execution plan for a query
const result = await products
  .find({ category: 'Electronics', price: { $lt: 2000 } })
  .sort({ price: 1 })
  .explain('executionStats');  // 'queryPlanner' for plan only

// Key fields to check:
console.log('Winning plan stage:', result.queryPlanner.winningPlan.stage);
// IXSCAN = index scan (good)
// COLLSCAN = collection scan (bad — add an index!)
// FETCH = fetching documents after index lookup (normal)
// COVERED = no document fetch needed (best!)

console.log('Docs examined:', result.executionStats.totalDocsExamined);
console.log('Keys examined:', result.executionStats.totalKeysExamined);
console.log('Docs returned:', result.executionStats.nReturned);
// Ideal: docsExamined == nReturned (no wasted work)
// Red flag: docsExamined >> nReturned (index not selective enough)

console.log('Time (ms):', result.executionStats.executionTimeMillis);

